import{_ as t,o as i,c as a,a3 as h}from"./chunks/framework.DX_KL3e0.js";const o="/help/screenshots/quan-tri/cai-dat.png",g="/help/screenshots/quan-tri/phien-dang-nhap.png",m=JSON.parse('{"title":"Cài đặt","description":"","frontmatter":{},"headers":[],"relativePath":"quan-tri/cai-dat.md","filePath":"quan-tri/cai-dat.md","lastUpdated":1782143716000}'),r={name:"quan-tri/cai-dat.md"};function s(c,n,l,e,p,u){return i(),a("div",null,[...n[0]||(n[0]=[h('<h1 id="cai-đat" tabindex="-1">Cài đặt <a class="header-anchor" href="#cai-đat" aria-label="Permalink to &quot;Cài đặt&quot;">​</a></h1><p>Trang <strong>Cài Đặt</strong> dành cho <strong>mọi người dùng</strong> để quản lý tài khoản cá nhân, tùy chọn ứng dụng và các phiên đăng nhập.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/settings</code>.</li><li><strong>Ai dùng được:</strong> mọi người dùng (cho tài khoản của chính mình). Admin/Quản lý chỉ <code>Xem</code> cài đặt <strong>hệ thống</strong> ở cấp module.</li><li><strong>Ba tab:</strong> Thông Tin · Cài Đặt Chung · Phiên Đăng Nhập.</li></ul></div><h2 id="tab-thong-tin" tabindex="-1">Tab Thông Tin <a class="header-anchor" href="#tab-thong-tin" aria-label="Permalink to &quot;Tab Thông Tin&quot;">​</a></h2><p>Cập nhật hồ sơ cá nhân.</p><ol><li>Đổi <strong>ảnh đại diện</strong> — nhấn <strong>Thay Đổi Ảnh Đại Diện</strong>, chọn ảnh (JPG/PNG/WebP, tối đa 1MB, tự cắt 300×300px).</li><li>Sửa <strong>Tên đầy đủ</strong>, <strong>Số điện thoại</strong>, <strong>Tiểu sử</strong>.</li><li>Nhấn <strong>Lưu Thay Đổi</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Email không đổi được</p><p>Trường <strong>Email</strong> chỉ để xem — không thể tự thay đổi.</p></div><p><img src="'+o+'" alt="Trang Cài đặt"></p><h2 id="tab-cai-đat-chung" tabindex="-1">Tab Cài Đặt Chung <a class="header-anchor" href="#tab-cai-đat-chung" aria-label="Permalink to &quot;Tab Cài Đặt Chung&quot;">​</a></h2><p>Gồm các thẻ:</p><ul><li><strong>Cài Đặt Ứng Dụng:</strong> chọn <strong>Ngôn ngữ</strong> (Tiếng Việt / English / 中文) và <strong>Giao Diện</strong> (Sáng / Tối / Tự động).</li><li><strong>Đổi Mật Khẩu:</strong> nhập <strong>mật khẩu hiện tại</strong>, <strong>mật khẩu mới</strong> (≥ 8 ký tự) và xác nhận, rồi <strong>Đổi Mật Khẩu</strong>.</li><li><strong>Thông Báo:</strong> bật/tắt <strong>Thông báo Telegram</strong> (nhận thông báo qua Telegram Bot).</li><li><strong>Xác Thực Hai Yếu Tố:</strong> tăng cường bảo mật khi đăng nhập.</li></ul><h2 id="tab-phien-đang-nhap" tabindex="-1">Tab Phiên Đăng Nhập <a class="header-anchor" href="#tab-phien-đang-nhap" aria-label="Permalink to &quot;Tab Phiên Đăng Nhập&quot;">​</a></h2><p>Xem các thiết bị đang đăng nhập (tên thiết bị, trình duyệt, hệ điều hành, IP, lần hoạt động cuối).</p><ul><li><strong>Đăng xuất</strong> một phiên: nhấn nút <em>Đăng xuất</em> trên dòng tương ứng.</li><li><strong>Đăng xuất tất cả phiên khác:</strong> nhấn liên kết ở cuối danh sách để thoát mọi thiết bị trừ thiết bị hiện tại.</li></ul><p><img src="'+g+'" alt="Tab Phiên Đăng Nhập — quản lý thiết bị đang đăng nhập"></p><div class="tip custom-block"><p class="custom-block-title">Mất quyền truy cập thiết bị cũ?</p><p>Dùng <strong>Đăng xuất tất cả phiên khác</strong> để vô hiệu hóa các phiên không còn dùng — hữu ích khi đổi máy hoặc nghi ngờ bị truy cập trái phép.</p></div><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/dang-nhap.html">Đăng nhập &amp; đăng xuất</a></p>',18)])])}const b=t(r,[["render",s]]);export{m as __pageData,b as default};
